<?php
require_once __DIR__ . '/includes/auth.php';
require_login();
$pdo=db();$pageTitle='Transaksi';$activePage='transaksi';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 if(($_POST['action']??'')==='delete'){
  if(!is_admin()){ $error='Kasir tidak memiliki akses menghapus transaksi.'; }
  else { $id=(int)$_POST['id'];$stmt=$pdo->prepare("SELECT status,nomor_transaksi FROM app_transaksi WHERE id=?");$stmt->execute([$id]);$trx=$stmt->fetch();if(!$trx){$error='Transaksi tidak ditemukan.';}elseif($trx['status']==='paid'){$error='Transaksi yang sudah dibayar tidak dapat dihapus, termasuk oleh admin.';}else{$pdo->prepare('DELETE FROM app_transaksi WHERE id=?')->execute([$id]);log_activity('hapus_transaksi','Menghapus transaksi '.$trx['nomor_transaksi']);flash('success','Transaksi berhasil dihapus.');header('Location: '.url('transaksi.php'));exit;}}
 }
}
$view=null;if(isset($_GET['view'])){$stmt=$pdo->prepare('SELECT t.*,u.nama kasir,p.nama_pelanggan pelanggan FROM app_transaksi t JOIN app_users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id_pelanggan=t.pelanggan_id WHERE t.id=?');$stmt->execute([(int)$_GET['view']]);$view=$stmt->fetch();if($view){$stmt=$pdo->prepare('SELECT * FROM app_detail_transaksi WHERE transaksi_id=?');$stmt->execute([$view['id']]);$view['details']=$stmt->fetchAll();}}
$q=trim($_GET['q']??'');$stmt=$pdo->prepare('SELECT t.*,u.nama kasir,p.nama_pelanggan pelanggan FROM app_transaksi t JOIN app_users u ON u.id=t.user_id LEFT JOIN pelanggan p ON p.id_pelanggan=t.pelanggan_id WHERE t.nomor_transaksi LIKE ? OR COALESCE(p.nama_pelanggan,\'Umum\') LIKE ? ORDER BY t.created_at DESC');$like='%'.$q.'%';$stmt->execute([$like,$like]);$rows=$stmt->fetchAll();
include __DIR__.'/includes/header.php';
if ($view): ?><div class="no-print" style="margin-bottom:15px"><a class="btn btn-primary" target="_blank" href="<?= e(url('nota.php?view=' . $view['id'] . '&print=1')) ?>">Cetak nota 58×40 mm</a></div><?php endif;
if($view): ?><section class="card" style="max-width:760px"><div class="section-head"><div><h2>Detail <?= e($view['nomor_transaksi']) ?></h2><p class="muted small"><?= e(date('d F Y, H:i',strtotime($view['created_at']))) ?> · Kasir <?= e($view['kasir']) ?></p></div><div class="toolbar no-print"><button class="btn btn-light btn-sm" onclick="window.print()">Cetak</button><a class="btn btn-light btn-sm" href="<?= e(url('transaksi.php')) ?>">Kembali</a></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Barang</th><th>Harga</th><th>Qty</th><th>Subtotal</th></tr></thead><tbody><?php foreach($view['details'] as $d): ?><tr><td><?= e($d['nama_barang']) ?></td><td><?= money($d['harga']) ?></td><td><?= e($d['qty']) ?></td><td class="amount"><?= money($d['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="total-box" style="max-width:300px;margin-left:auto"><div class="total-line"><span>Subtotal</span><strong><?= money($view['subtotal']) ?></strong></div><div class="total-line grand"><span>Total</span><span><?= money($view['total']) ?></span></div><div class="total-line"><span>Bayar</span><span><?= money($view['bayar']) ?></span></div><div class="total-line"><span>Kembalian</span><strong><?= money($view['kembalian']) ?></strong></div></div></section><?php else: ?><section class="card"><div class="section-head"><div><h2>Riwayat transaksi</h2><p class="muted small">Transaksi berstatus paid tersimpan sebagai riwayat dan tidak dapat dihapus.</p></div><a class="btn btn-primary" href="<?= e(url('kasir.php')) ?>">+ Transaksi baru</a></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form class="search-row no-print" method="get"><input class="input" name="q" value="<?= e($q) ?>" placeholder="Cari nomor transaksi atau pelanggan..."><button class="btn btn-light">Cari</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Transaksi</th><th>Pelanggan</th><th>Kasir</th><th>Total</th><th>Status</th><th class="no-print">Aksi</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['nomor_transaksi']) ?></strong><div class="muted small"><?= e(date('d/m/Y H:i',strtotime($row['created_at']))) ?></div></td><td><?= e($row['pelanggan']?:'Umum') ?></td><td><?= e($row['kasir']) ?></td><td class="amount"><?= money($row['total']) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="no-print"><div class="actions"><a class="btn btn-light btn-sm" href="<?= e(url('transaksi.php?view='.$row['id'])) ?>">Detail</a><?php if(is_admin()&&$row['status']!=='paid'): ?><form method="post" onsubmit="return confirm('Hapus transaksi ini?')"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($row['id']) ?>"><button class="btn btn-danger btn-sm">Hapus</button></form><?php endif; ?></div></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="empty">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; include __DIR__.'/includes/footer.php'; ?>
